func qualDRWANativeStartupFixtureDir(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	for name, fixture := range qualDRWANativeStartupFixtures {
		body := []byte(fixture.body)
		require.Equal(t, fixture.sha256, fmt.Sprintf("%x", sha256.Sum256(body)), name)
		require.NoError(t, os.WriteFile(filepath.Join(dir, name), body, 0600))
	}
	return dir
}
